ALTER TABLE public.payments ADD COLUMN migrated_expense_id uuid REFERENCES public.rental_expenses(id);
ALTER TABLE public.rental_expenses ADD COLUMN source_payment_id uuid UNIQUE REFERENCES public.payments(id);
INSERT INTO public.rent_charges(tenancy_id,period,due_on,amount) SELECT t.id,date_trunc('month',p.paid_on)::date,p.paid_on,t.rent_amount FROM public.payments p JOIN public.tenancies t ON t.property_id=p.property_id AND t.tenant_id=p.tenant_id WHERE p.category='rent' AND p.charge_id IS NULL ON CONFLICT DO NOTHING;
INSERT INTO public.rental_expenses(tenancy_id,property_id,category,amount,paid_on,note,payer,reimbursement,source_payment_id) SELECT t.id,p.property_id,p.category,p.amount,p.paid_on,p.notes,'tenant','rent_credit',p.id FROM public.payments p JOIN public.tenancies t ON t.property_id=p.property_id AND t.tenant_id=p.tenant_id WHERE p.kind='expense' AND p.notes ILIKE '%inquilino%' AND p.notes ILIKE '%descont%' AND p.migrated_expense_id IS NULL ON CONFLICT(source_payment_id) DO NOTHING;
UPDATE public.payments p SET migrated_expense_id=e.id FROM public.rental_expenses e WHERE e.source_payment_id=p.id;
UPDATE public.payments p SET charge_id=c.id FROM public.rent_charges c JOIN public.tenancies t ON t.id=c.tenancy_id WHERE p.category='rent' AND p.charge_id IS NULL AND p.property_id=t.property_id AND p.tenant_id=t.tenant_id AND c.period=date_trunc('month',p.paid_on)::date;
CREATE FUNCTION public.validate_contract_edit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.landlord_id<>OLD.landlord_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.property_id<>OLD.property_id THEN RAISE EXCEPTION 'No puedes cambiar las partes del contrato'; END IF; IF NEW.end_date IS NOT NULL AND NEW.end_date<NEW.start_date THEN RAISE EXCEPTION 'Fechas inválidas'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER contract_protect BEFORE UPDATE ON public.tenancies FOR EACH ROW EXECUTE FUNCTION public.validate_contract_edit();
CREATE POLICY "Tenant calendar records" ON public.maintenance_records FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.tenancies t WHERE t.property_id=maintenance_records.property_id AND t.tenant_id=auth.uid() AND t.status='active'));
CREATE FUNCTION public.protect_notification_edit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id<>OLD.user_id OR NEW.title<>OLD.title OR NEW.path<>OLD.path OR NEW.reference_id IS DISTINCT FROM OLD.reference_id THEN RAISE EXCEPTION 'Solo puedes marcar leído'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER notification_read_only BEFORE UPDATE ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.protect_notification_edit();
CREATE POLICY "Read messages by contract" ON public.messages AS RESTRICTIVE FOR SELECT TO authenticated USING(tenancy_id IS NULL OR public.contract_party(tenancy_id));
CREATE FUNCTION public.record_inventory_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity_log(tenancy_id,event,reference_id,actor_id) VALUES(NEW.tenancy_id,CASE WHEN NEW.agreed_at IS DISTINCT FROM OLD.agreed_at THEN 'Inventario aceptado' ELSE 'Inventario actualizado' END,NEW.id,auth.uid()); RETURN NEW; END; $$;
CREATE TRIGGER inventory_activity AFTER UPDATE ON public.inventories FOR EACH ROW EXECUTE FUNCTION public.record_inventory_activity();